/* @autogenerated */
package net.civeira.phylax.feature.oauth.delegatelogin.infrastructure.driven;

import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.sql.NotUniqueException;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderReference;
import net.civeira.phylax.feature.identity.user.domain.UserReference;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.UserFederatedIdentity;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.UserFederatedIdentityChangeSet;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.gateway.UserFederatedIdentityCommandRepositoryGateway;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.gateway.UserFederatedIdentityFilter;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.gateway.FederatedIdentityGateway;

/**
 * Federated identity links stored in the Access entity {@code user-federated-identity}.
 *
 * Responsibilities: - Find and record links between provider subjects and users.
 *
 * Design notes: - Uses the command repository, so it reads the primary and its writes go through
 * events and changelog. - The unique index (login-provider, subject) decides concurrent links.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class FederatedIdentityAdapter implements FederatedIdentityGateway {
  /**
   * Repository of the generated entity.
   */
  private final UserFederatedIdentityCommandRepositoryGateway repository;

  @Override
  public Optional<String> linkedUser(String providerUid, String subject) {
    return repository.findForUpdate(bySubject(providerUid, subject))
        .map(UserFederatedIdentity::getUserUid);
  }

  @Override
  public String link(String providerUid, String subject, String userUid) {
    Optional<String> existing = linkedUser(providerUid, subject);
    if (existing.isPresent()) {
      return existing.get();
    }
    try {
      return repository.create(UserFederatedIdentity.create(new UserFederatedIdentityChangeSet()
          .newUid().loginProvider(TenantLoginProviderReference.of(providerUid)).subject(subject)
          .user(UserReference.of(userUid)))).getUserUid();
    } catch (NotUniqueException ex) {
      // A concurrent first access of the same subject won: its link is the valid one.
      return linkedUser(providerUid, subject).orElseThrow(() -> ex);
    }
  }

  @Override
  public boolean isLinkedTo(String userUid, String providerUid) {
    return repository
        .countForUpdate(UserFederatedIdentityFilter.builder().user(UserReference.of(userUid))
            .loginProvider(TenantLoginProviderReference.of(providerUid)).build()) > 0;
  }

  @Override
  public boolean hasLinks(String userUid) {
    return repository.countForUpdate(
        UserFederatedIdentityFilter.builder().user(UserReference.of(userUid)).build()) > 0;
  }

  private static UserFederatedIdentityFilter bySubject(String providerUid, String subject) {
    return UserFederatedIdentityFilter.builder()
        .loginProvider(TenantLoginProviderReference.of(providerUid)).subject(subject).build();
  }
}
